class Main {
  static int f() { int[] xs = new int[1]; return xs[2]; }
  public static void main(String[] args) {
    try { f(); } catch (ArrayIndexOutOfBoundsException e) {
      System.out.println(e.getStackTrace()[0].getMethodName());
    }
  }
}

